create policy "Enable delete for users based on user_id"
on "public"."participants"
as permissive
for delete
to authenticated
using ((( SELECT auth.uid() AS uid) = participant_id));


create policy "Enable insert for authenticated members only"
on "public"."participants"
as permissive
for insert
to authenticated
with check (true);


create policy "Enable read access for all authenticated members"
on "public"."participants"
as permissive
for select
to authenticated
using (true);


create policy "Enable delete for committees and admin"
on "public"."workshops"
as permissive
for delete
to authenticated
using ((authorize('committee.create'::app_permission) OR authorize('read-only-committee.create'::app_permission) OR authorize('administrator.create'::app_permission)));


create policy "Enable insert for committees and admin only"
on "public"."workshops"
as permissive
for insert
to authenticated
with check ((authorize('committee.create'::app_permission) OR authorize('read-only-committee.create'::app_permission) OR authorize('administrator.create'::app_permission)));


create policy "Enable read access for all members"
on "public"."workshops"
as permissive
for select
to authenticated
using (true);


create policy "Enable update for committees and admin"
on "public"."workshops"
as permissive
for update
to authenticated
using ((authorize('committee.create'::app_permission) OR authorize('read-only-committee.create'::app_permission) OR authorize('administrator.create'::app_permission)));



